/// <summary>
/// Helper class to complete the purchase order processes.
/// </summary>
public class METPurchaseOrderProcessHelper
{
}

Method.Source:
/// <summary>
/// Confirm the purchase order.
/// </summary>
/// <param name = "_purchId">Purchase order ID</param>
public static void confirmPurchaseOrder(PurchId _purchId)
{
    TransDate                   transDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    PurchFormLetter             purchFormLetter;
    PurchFormletterParmData     purchFormLetterParmData;
    PurchParmUpdate             purchParmUpdate;
    PurchParmTable              purchParmTable;
    PurchTable                  purchTable;

    purchTable = PurchTable::find(_purchId);

    ttsBegin;

    purchFormLetterParmData = PurchFormletterParmData::newData(DocumentStatus::PurchaseOrder,
                                                               VersioningUpdateType::Initial);

    purchFormLetterParmData.parmOnlyCreateParmUpdate(true);
    purchFormLetterParmData.createData(false);
    purchParmUpdate = purchFormLetterParmData.parmParmUpdate();

    purchParmTable.clear();
    purchParmTable.TransDate                = transDate;
    purchParmTable.DocumentDate             = transDate;
    purchParmTable.Ordering                 = DocumentStatus::PurchaseOrder;
    purchParmTable.ParmJobStatus            = ParmJobStatus::Waiting;
    purchParmTable.PurchId                  = purchTable.PurchId;
    purchParmTable.PurchName                = purchTable.PurchName;
    purchParmTable.DeliveryName             = purchTable.DeliveryName;
    purchParmTable.DeliveryPostalAddress    = purchTable.DeliveryPostalAddress;
    purchParmTable.OrderAccount             = purchTable.OrderAccount;
    purchParmTable.CurrencyCode             = purchTable.CurrencyCode;
    purchParmTable.InvoiceAccount           = purchTable.InvoiceAccount;
    purchParmTable.ParmId                   = purchParmUpdate.ParmId;
    purchParmTable.insert();

    purchFormLetter = PurchFormLetter::construct(DocumentStatus::PurchaseOrder);
    purchFormLetter.transDate(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
    purchFormLetter.proforma(false);
    purchFormLetter.specQty(PurchUpdate::All);
    purchFormLetter.purchTable(purchTable);

    purchFormLetter.parmParmTableNum(purchParmTable.ParmId);
    purchFormLetter.parmId(purchParmTable.ParmId);
    purchFormLetter.purchParmUpdate(purchFormLetterParmData.parmParmUpdate());
    purchFormLetter.run();

    ttsCommit;
}

/// <summary>
/// Post the product receipt of the purchase order.
/// </summary>
/// <param name = "_purchTable">Purchase order ID</param>
/// <param name = "_invoiceId">Invoice ID</param>
public static void postPurchaseOrderProductReceipt(PurchTable _purchTable, InvoiceId _invoiceId)
{
    PurchId                     purchId;
    PurchLine                   purchLine;
    PurchParmLine               purchParmLine;
    PurchParmTable              purchParmTable;
    PurchFormLetter             purchFormLetter;
    PurchParmUpdate             purchParmUpdate;
    PurchFormletterParmData     purchFormLetterParmData;

    ttsBegin;
    //Create PurchParamUpdate table
    purchFormLetterParmData = PurchFormletterParmData::newData(DocumentStatus::PackingSlip, VersioningUpdateType::Initial);

    purchFormLetterParmData.parmOnlyCreateParmUpdate(true);
    purchFormLetterParmData.createData(false);

    purchParmUpdate = purchFormLetterParmData.parmParmUpdate();

    //Set PurchParmTable table
    purchParmTable.clear();

    purchParmTable.Num                      = _invoiceId;
    purchParmTable.ParmId                   = purchParmUpdate.ParmId;
    purchParmTable.PurchId                  = _purchTable.PurchId;
    purchParmTable.TransDate                = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    purchParmTable.Ordering                 = DocumentStatus::PackingSlip;
    purchParmTable.PurchName                = _purchTable.PurchName;
    purchParmTable.DeliveryName             = _purchTable.DeliveryName;
    purchParmTable.OrderAccount             = _purchTable.OrderAccount;
    purchParmTable.CurrencyCode             = _purchTable.CurrencyCode;
    purchParmTable.ParmJobStatus            = ParmJobStatus::Waiting;
    purchParmTable.InvoiceAccount           = _purchTable.InvoiceAccount;
    purchParmTable.DeliveryPostalAddress    = _purchTable.DeliveryPostalAddress;

    purchParmTable.insert();

    //Set PurchParmLine table
    while select purchLine
        where purchLine.PurchId == _purchTable.purchId
    {
        purchParmLine.InitFromPurchLine(purchLine);

        purchParmLine.ReceiveNow    = purchLine.PurchQty;
        purchParmLine.ParmId        = purchParmTable.ParmId;
        purchParmLine.TableRefId    = purchParmTable.TableRefId;

        purchParmLine.setQty(DocumentStatus::PackingSlip, false, true);
        purchParmLine.setLineAmount();
        purchParmLine.insert();
    }

    purchFormLetter = PurchFormLetter::construct(DocumentStatus::PackingSlip);

    purchFormLetter.transDate(systemDateGet());
    purchFormLetter.proforma(false);
    purchFormLetter.specQty(PurchUpdate::All);
    purchFormLetter.purchTable(_purchTable);
    purchFormLetter.parmParmTableNum(purchParmTable.ParmId);
    purchFormLetter.parmId(purchParmTable.ParmId);
    purchFormLetter.purchParmUpdate(purchFormLetterParmData.parmParmUpdate());
    purchFormLetter.run();
    ttsCommit;
}
